template<typename T>
void add_eas_records(const std::string& table_name,
                     const std::vector<T>& records) {
  sqlite::connect(db_path)
      .and_then([&](auto&& conn) {
        return sqlgen::insert_into<T>(records)(conn);
      })
      .value();
}

void modify_eas_records_by_id(const std::string& table_name,
                              const int record_id,
                              const std::string& col_name,
                              const auto& new_value) {
  sqlite::connect(db_path)
      .and_then([&](auto&& conn) {
        if (table_name == "Student") {
          auto set_clause = rfl::to_field<student>(col_name).set(new_value);
          return sqlgen::update<student>(set_clause) |
                 where(rfl::to_field<student>("SNo") == record_id)(conn);
        } else if (table_name == "Course") {
          auto set_clause = rfl::to_field<course>(col_name).set(new_value);
          return sqlgen::update<course>(set_clause) |
                 where(rfl::to_field<course>("CID") == record_id)(conn);
        } else if (table_name == "Score") {
          auto set_clause = rfl::to_field<score>(col_name).set(new_value);
          return sqlgen::update<score>(set_clause) |
                 where(rfl::to_field<score>("ScID") == record_id)(conn);
        } else if (table_name == "Major") {
          auto set_clause = rfl::to_field<major>(col_name).set(new_value);
          return sqlgen::update<major>(set_clause) |
                 where(rfl::to_field<major>("MID") == record_id)(conn);
        }
        throw std::runtime_error("Unknown table name");
      })
      .value();
}

void delete_eas_records_by_id(const std::string& table_name,
                               const std::string& record_id) {
  sqlite::connect(db_path)
      .and_then([&](auto&& conn) {
        if (table_name == "Student") {
          return sqlgen::delete_from<student>() |
                 where(rfl::to_field<student>("SNo") == record_id)(conn);
        } else if (table_name == "Course") {
          return sqlgen::delete_from<course>() |
                 where(rfl::to_field<course>("CID") == std::stoi(record_id))(conn);
        } else if (table_name == "Score") {
          return sqlgen::delete_from<score>() |
                 where(rfl::to_field<score>("ScID") == std::stoi(record_id))(conn);
        } else if (table_name == "Major") {
          return sqlgen::delete_from<major>() |
                 where(rfl::to_field<major>("MID") == std::stoi(record_id))(conn);
        }
        throw std::runtime_error("Unknown table name");
      })
      .value();
}
