```python
#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
    try {
        // Remove existing database file if it exists
        std::filesystem::remove("test_db.sqlite");

        // Connect to SQLite database
        auto conn = sqlgen::sqlite::connect("test_db.sqlite");

        // Create Product table
        conn.and_then(sqlgen::drop<Product> | sqlgen::if_exists)
            .and_then(sqlgen::create<Product>);

        // Begin transaction
        conn.and_then(sqlgen::begin_transaction);

        // Insert products
        conn.and_then([&](auto& c) {
            return sqlgen::insert(c, products.begin(), products.end());
        });

        // Commit transaction
        conn.and_then(sqlgen::commit);

        return true;
    } catch (...) {
        return false;
    }
}

}  // namespace batch_insert_products
```

