```python
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_course_enrollment_stats {

struct Course {
  sqlgen::PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  sqlgen::PrimaryKey<int> enrollment_id;
  sqlgen::ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

struct CourseStatsView {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

/**
 * Function: Calculate enrollment statistics per course.
 * 
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  // Connect to SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

  // Create tables
  sqlgen::create_table_if_not_exists<Course>(conn);
  sqlgen::create_table_if_not_exists<Enrollment>(conn);

  // Query the database for course stats
  const auto stats_view = sqlgen::select_from<CourseStatsView>(
    sqlgen::make_query(
      "SELECT c.title, COUNT(e.enrollment_id) as student_count, AVG(e.grade) as avg_grade "
      "FROM Course c "
      "LEFT JOIN Enrollment e ON c.course_id = e.course_id "
      "GROUP BY c.course_id, c.title"
    )
  )(conn);

  // Convert view to CourseStats
  std::vector<CourseStats> result;
  for (const auto& stat : stats_view.value()) {
    result.push_back(CourseStats{
      .title = stat.title,
      .student_count = stat.student_count,
      .avg_grade = stat.avg_grade
    });
  }

  return result;
}

}  // namespace query_course_enrollment_stats
