#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_daily_traffic_metrics {

struct PageVisit {
  sqlgen::PrimaryKey<int> visit_id;
  std::string url;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> visit_time;
};

struct DailyTraffic {
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

struct DailyTrafficView {
  static constexpr const char* tablename = "DailyTrafficView";
  static constexpr bool is_view = true;
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

  // Create view with the required query logic
  const auto create_view_sql = R"(
    CREATE VIEW IF NOT EXISTS DailyTrafficView AS
    SELECT strftime('%Y-%m-%d', visit_time) as visit_date, 
           COUNT(*) as total_visits, 
           COUNT(DISTINCT url) as unique_pages
    FROM PageVisit
    GROUP BY visit_date
    ORDER BY visit_date;
  )";
  conn.execute(create_view_sql).value();

  // Read data from the view
  auto result = sqlgen::read<std::vector<DailyTrafficView>>(conn);
  if (!result) {
    throw std::runtime_error("Failed to read from DailyTrafficView");
  }

  // Convert to DailyTraffic objects
  std::vector<DailyTraffic> traffic_data;
  for (const auto& row : *result) {
    traffic_data.push_back({
      .visit_date = row.visit_date,
      .total_visits = row.total_visits,
      .unique_pages = row.unique_pages
    });
  }

  // Drop the temporary view
  conn.execute("DROP VIEW IF EXISTS DailyTrafficView").value();

  return traffic_data;
}

}  // namespace query_daily_traffic_metrics
