#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_high_value_orders {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct OrderView {
  static constexpr const char* tablename = "HighValueOrderView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string name;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Create the view based on the reference SQL query
  const auto create_view = sqlgen::CreateAs<OrderView>(
    sqlgen::SelectFrom<Order>()
      .inner_join<Customer>()
      .on(Order{}.customer_id == Customer{}.customer_id)
      .where(Order{}.total_amount > 1000)
      .order_by(sqlgen::desc(Order{}.total_amount))
  );

  // Execute the creation of the view
  sqlgen::execute(conn, create_view).value();

  // Read the data from the created view
  const auto result = sqlgen::read<std::vector<OrderView>>(conn).value();

  return result;
}

}  // namespace query_high_value_orders
