#pragma once

#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the database
    auto connection = sqlite::connect("test_db.sqlite").value();

    // Start with base query
    auto query = read<std::vector<Book>> | from<"Book">;

    // Add WHERE clauses dynamically based on provided filters
    if (filters.title_keyword.has_value()) {
        query = query | where<"title"_field.like>(filters.title_keyword.value());
    }

    if (filters.min_year.has_value()) {
        query = query | where<"year"_field >=>(filters.min_year.value());
    }

    if (filters.genre.has_value()) {
        query = query | where<"genre"_field ==>(filters.genre.value());
    }

    if (filters.max_price.has_value()) {
        query = query | where<"price"_field <=>(filters.max_price.value());
    }

    // Execute the query and return results
    return connection.execute(query).value();
}

}  // namespace query_search_books_by_criteria
