    double price;
  };

  bool manage_indexes() {
    try {
      // Connect to SQLite database
      auto conn = sqlgen::sqlite::connect("test_db.sqlite");

      // Create the Product table first to ensure it exists
      sqlgen::create_table_if_not_exists<Product>(conn);

