              Product, decltype(rfl::make_field<"category">(std::string()))>(
              "idx_product_category", rfl::make_field<"category">(std::string()))
              .if_not_exists(true));

      // Create unique index on sku
      sqlgen::execute(
          conn,
          sqlgen::to_create_unique_index<
              Product, decltype(rfl::make_field<"sku">(std::string()))>(
              "idx_product_sku", rfl::make_field<"sku">(std::string()))
