```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    if (ids.empty()) {
        return true; // Nothing to delete
    }

    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        return false;
    }

    auto conn = *conn_result;
    auto transaction_result = conn->begin_transaction();
    if (!transaction_result) {
        return false;
    }

    try {
        for (const auto& id : ids) {
            auto doc = Document{};
            doc.doc_id = id;
            doc.is_deleted = 1;
            doc.deleted_at = sqlgen::DateTime::now();

            const auto update_result = sqlgen::write(*conn, doc);
            if (!update_result) {
                conn->rollback();
                return false;
            }
        }

        const auto commit_result = conn->commit();
        return commit_result.has_value();
    } catch (...) {
        conn->rollback();
        return false;
    }
}

}  // namespace soft_delete_records
```

