```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  try {
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Start transaction
    conn.execute("BEGIN TRANSACTION");

    // Check if sender has sufficient funds and deduct amount
    const auto update_sender = 
        "UPDATE Account SET balance = balance - ? WHERE account_id = ? AND balance >= ?";
    const auto sender_result = conn.execute(update_sender, amount, from_account_id, amount);

    // If no rows were affected, sender doesn't exist or has insufficient funds
    if (sender_result.rows_affected() == 0) {
      conn.execute("ROLLBACK");
      return false;
    }

    // Add amount to receiver's balance
    const auto update_receiver = 
        "UPDATE Account SET balance = balance + ? WHERE account_id = ?";
    const auto receiver_result = conn.execute(update_receiver, amount, to_account_id);

    // If no rows were affected, receiver doesn't exist
    if (receiver_result.rows_affected() == 0) {
      conn.execute("ROLLBACK");
      return false;
    }

    // Commit transaction
    conn.execute("COMMIT");
    return true;

  } catch (...) {
    // If any exception occurs, rollback and return false
    try {
      auto conn = sqlgen::sqlite::connect("test_db.sqlite");
      conn.execute("ROLLBACK");
    } catch (...) {
      // Ignore rollback errors
    }
    return false;
  }
}

}  // namespace transaction_transfer_funds
