```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_order_status {

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  std::string status;
  sqlgen::DateTime order_date;
  double total_amount;
};

int update_order_status() {
    // Connect to the SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        throw std::runtime_error("Failed to connect to database: " + 
                                std::string(conn_result.error().what()));
    }

    auto conn = std::move(*conn_result);

    int total_rows_affected = 0;

    // Begin transaction for atomicity
    auto transaction_result = conn.begin_transaction();
    if (!transaction_result) {
        throw std::runtime_error("Failed to begin transaction: " + 
                                std::string(transaction_result.error().what()));
    }

    try {
        // Update pending orders older than 7 days to expired
        auto update_expired_result = sqlgen::update<Order>(conn)
            .set(Order{}.status, "expired")
            .where(Order{}.status == "pending" && 
                   Order{}.order_date < sqlgen::date_now("-7 days"))
            .execute();

        if (!update_expired_result) {
            conn.rollback();
            throw std::runtime_error("Failed to update expired orders: " + 
                                    std::string(update_expired_result.error().what()));
        }

        int expired_rows_affected = update_expired_result.value();
        total_rows_affected += expired_rows_affected;

        // Update shipped orders to delivered (simulated)
        auto update_delivered_result = sqlgen::update<Order>(conn)
            .set(Order{}.status, "delivered")
            .where(Order{}.status == "shipped")
            .execute();

        if (!update_delivered_result) {
            conn.rollback();
            throw std::runtime_error("Failed to update delivered orders: " + 
                                    std::string(update_delivered_result.error().what()));
        }

        int delivered_rows_affected = update_delivered_result.value();
        total_rows_affected += delivered_rows_affected;

        // Commit the transaction
        auto commit_result = conn.commit();
        if (!commit_result) {
            throw std::runtime_error("Failed to commit transaction: " + 
                                    std::string(commit_result.error().what()));
        }

    } catch (...) {
        conn.rollback();
        throw;
    }

    return total_rows_affected;
}

} // namespace update_order_status
```

