#include <vector>

namespace schema_create_view_sales_summary {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  try {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Begin transaction
    auto txn = conn->begin_transaction();

    // Construct the SELECT query for the view
    auto query = sqlgen::select_from<Sale, Product>(
      sqlgen::columns(
        "name"_c.as("product_name"),
        sqlgen::sum("quantity"_c).as("total_quantity"),
        sqlgen::sum("amount"_c).as("total_revenue")
      )
    ).where("Sale.product_id"_c == "Product.product_id"_c)
    .group_by("Product.name"_c);

    // Create the view with DROP IF EXISTS to handle re-creation
    auto drop_stmt = sqlgen::drop_view<SalesSummary> | sqlgen::if_exists;
    auto drop_sql = sqlgen::sqlite::to_sql(drop_stmt);
    conn->execute(drop_sql);

    // Create the view
    auto create_view_stmt = sqlgen::create_as<SalesSummary>(query);
    auto create_view_sql = sqlgen::sqlite::to_sql(create_view_stmt);
    conn->execute(create_view_sql);

    // Commit transaction
    txn->commit();

    return true;
  } catch (const std::exception& e) {
    return false;
  }
}

}  // namespace schema_create_view_sales_summary
