```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace right_join_departments_projects {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::optional<std::string> department_name;
  std::string project_name;
};

/**
 * description: right_join_departments_projects.
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  // Connect to the SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Perform a right join between Department and Project tables
  // Since SQL doesn't directly support RIGHT JOIN, we'll swap the tables and use LEFT JOIN
  // Projects (all records) with matching Departments (if they exist)
  const auto result = sqlgen::read<std::vector<DepProj>>(
    conn,
    sqlgen::select_from<Project>()
      .left_join<Department>(sqlgen::on(Project::department_id == Department::department_id))
      .fields(
        Department::name.as<DepProj::department_name>(),
        Project::name.as<DepProj::project_name>()
      )
  ).value();

  return result;
}

}  // namespace right_join_departments_projects
