#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_temporal_data {

struct Event {
  sqlgen::PrimaryKey<int> event_id;
  std::string event_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  std::optional<sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">> end_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct TemporalAnalysis {
  int event_id;
  std::string event_name;
  int start_day;
  int start_month;
  int start_year;
  int start_hour;
  int start_minute;
  int start_second;
  int start_weekday;
  int64_t start_epoch;
  std::optional<double> duration_days;
};

/**
 * @brief Analyze temporal data for a collection of events.
 *
 * Inserts the provided events into a temporary SQLite table, runs a query
 * to extract date/time parts and compute duration, and returns the results
 * as a vector of TemporalAnalysis.
 *
 * @param events Vector of Event records to analyze.
 * @return std::vector<TemporalAnalysis> Analysis results for each event that has an end_time.
 */
std::vector<TemporalAnalysis> analyze_temporal_data (const std::vector<Event>& events)  {
  auto session = sqlgen::sqlite::connect("test_db.sqlite");

  sqlgen::exec(session, sqlgen::drop<sqlgen::if_exists>(sqlgen::table<Event>()));
  sqlgen::exec(session, sqlgen::create_table<sqlgen::if_not_exists>(sqlgen::table<Event>()));

  for (const auto& event : events) {
      sqlgen::exec(session, sqlgen::insert<sqlgen::into>(event));
  }

  auto select_query = sqlgen::select(
    col(&Event::event_id),
    col(&Event::event_name),
    sqlgen::as(sqlgen::day(col(&Event::start_time)), "start_day"),
    sqlgen::as(sqlgen::month(col(&Event::start_time)), "start_month"),
    sqlgen::as(sqlgen::year(col(&Event::start_time)), "start_year"),
    sqlgen::as(sqlgen::hour(col(&Event::start_time)), "start_hour"),
    sqlgen::as(sqlgen::minute(col(&Event::start_time)), "start_minute"),
    sqlgen::as(sqlgen::second(col(&Event::start_time)), "start_second"),
    sqlgen::as(sqlgen::weekday(col(&Event::start_time)), "start_weekday"),
    sqlgen::as(sqlgen::unixepoch(col(&Event::start_time)), "start_epoch"),
    sqlgen::as(sqlgen::days_between(col(&Event::start_time), col(&Event::end_time)), "duration_days")
  ).from(sqlgen::table<Event>())
   .where(col(&Event::end_time).is_not_null());

  return sqlgen::exec(session, select_query);
}

}  // namespace analyze_temporal_data
```

