/**
 * Analyze social network data by connecting to SQLite database test_db.sqlite.
 * Performs various analyses on User and Friendship data.
 */
void analyze_social_network() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto db = sqlite::connect("test_db.sqlite").value();

  // Drop tables if they exist
  db = drop<User> | if_exists(db);
  db = drop<Friendship> | if_exists(db);

  // Create tables
  db = create_table<User>(db);
  db = create_table<Friendship>(db);

  // 1. Use SELF-JOIN to find mutual friends
  const auto mutual_friends_query = R"(
    SELECT u1.username, u2.username, COUNT(f1.user_id2) as mutual_friends
    FROM User u1
    INNER JOIN Friendship f1 ON u1.user_id = f1.user_id1
    INNER JOIN Friendship f2 ON f1.user_id2 = f2.user_id1
    INNER JOIN User u2 ON f2.user_id2 = u2.user_id
    WHERE u1.user_id < u2.user_id
      AND EXISTS (
        SELECT 1 FROM Friendship f3 
        WHERE f3.user_id1 = u1.user_id AND f3.user_id2 = u2.user_id
      )
    GROUP BY u1.user_id, u2.user_id
    HAVING COUNT(f1.user_id2) > 0
  )";

  const auto mutual_friends_result = raw_sql<std::vector<MutualFriend>>(mutual_friends_query)(db);

  // 2. Use nested query to find users with more than N friends
  const auto high_degree_users_query = R"(
    SELECT u.user_id, u.username, COUNT(f.user_id2) as friend_count
    FROM User u
    LEFT JOIN Friendship f ON u.user_id = f.user_id1
    GROUP BY u.user_id, u.username
    HAVING friend_count > (
      SELECT AVG(friend_count) 
      FROM (SELECT COUNT(*) as friend_count FROM Friendship GROUP BY user_id1)
    )
    ORDER BY friend_count DESC
  )";

  const auto high_degree_users_result = raw_sql<std::vector<HighDegreeUser>>(high_degree_users_query)(db);

  // 3. Find friend-of-friend relationships
  const auto friend_of_friend_query = R"(
    SELECT DISTINCT u1.username as user_name, u3.username as friend_of_friend_name
    FROM User u1
