          .join<"customer_id"_col, "customer_id"_col>()
          .join<"order_id"_col, "order_id"_col>()
          .order_by<"amount"_col>(sqlgen::Ordering::DESC)
          .execute(db))
      .value();
}

}  // namespace join_orders_customers_payments

