```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto connection = sqlgen::sqlite::connect("test_db.sqlite")
                     .and_then(sqlgen::pragma_foreign_keys_on)
                     .and_then(sqlgen::drop<Parent> | sqlgen::if_exists)
                     .and_then(sqlgen::drop<Child> | sqlgen::if_exists)
                     .and_then(sqlgen::begin_transaction)
                     .and_then(sqlgen::create_table<Parent>)
                     .and_then(sqlgen::create_table<Child>)
                     .value();

  // Insert parent record
  auto parent = Parent{.parent_id = 1, .name = "Test Parent"};
  connection = connection.and_then(sqlgen::insert(parent)).value();

  // Insert child records
  auto child1 = Child{.child_id = 1, .parent_id = 1, .note = "Child 1"};
  auto child2 = Child{.child_id = 2, .parent_id = 1, .note = "Child 2"};
  connection = connection.and_then(sqlgen::insert(child1))
                     .and_then(sqlgen::insert(child2))
                     .value();

  // Verify children exist before deletion
  auto child_count_before = connection.and_then(
      sqlgen::count<Child>(sqlgen::where(
          sqlgen::field<"parent_id"> = sqlgen::val(1)))).value();

  if (child_count_before != 2) {
    return false;
  }

  // Delete parent record - this should cascade delete children
  connection = connection.and_then(
      sqlgen::delete_from<Parent>(sqlgen::where(
          sqlgen::field<"parent_id"> = sqlgen::val(1))))
                     .and_then(sqlgen::commit)
                     .value();

  // Verify that children were deleted automatically
  auto child_count_after = sqlgen::sqlite::connect("test_db.sqlite")
                            .and_then(sqlgen::pragma_foreign_keys_on)
                            .and_then(sqlgen::count<Child>(sqlgen::where(
                                sqlgen::field<"parent_id"> = sqlgen::val(1))))
                            .value();

  // Clean up tables
  sqlgen::sqlite::connect("test_db.sqlite")
      .and_then(sqlgen::drop<Parent> | sqlgen::if_exists)
      .and_then(sqlgen::drop<Child> | sqlgen::if_exists)
      .value();

  // Return true if children were cascade deleted (count should be 0)
  return child_count_after == 0;
}

}  // namespace cascade_delete_demo
```

