#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace column_is_null_checks {

struct Profile {
  sqlgen::PrimaryKey<int> profile_id;
  std::string display_name;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

struct Result {
  int profile_id;
  std::string display_name;
};

std::vector<Result> column_is_null_checks() {
  // Connect to SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

  // Create the Profile table if it doesn't exist
  sqlgen::create_table_if_not_exists<Profile>(conn);

  // Insert sample data for testing
  Profile p1{.profile_id = 1, .display_name = "Alice", .bio = "Developer", .avatar_url = std::nullopt};
  Profile p2{.profile_id = 2, .display_name = "Bob", .bio = std::nullopt, .avatar_url = "http://example.com/bob.jpg"};
  Profile p3{.profile_id = 3, .display_name = "Charlie", .bio = std::nullopt, .avatar_url = std::nullopt};

  sqlgen::write(conn, p1);
  sqlgen::write(conn, p2);
  sqlgen::write(conn, p3);

  // Query for profiles where bio IS NULL
  const auto query = sqlgen::select_from<Profile>()
                     .columns<&Profile::profile_id, &Profile::display_name>()
                     .where(
                       sqlgen::is_null(&Profile::bio)
                     );

  // Execute query and get results
  auto result = sqlgen::read<std::vector<std::tuple<int, std::string>>>(conn, query).value();

  // Convert tuples to Result structs
  std::vector<Result> results;
  for (const auto& [profile_id, display_name] : result) {
    results.push_back(Result{profile_id, display_name});
  }

  return results;
}

}  // namespace column_is_null_checks
