namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  try {
    // Connect to SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

    // Create Account table
    sqlgen::write(conn, sqlgen::create_table_if_not_exists<Account>());

    // Insert initial data
    sqlgen::write(conn, Account{.account_id = 1, .balance = 1000.0, .status = "active"});
    sqlgen::write(conn, Account{.account_id = 2, .balance = 2500.0, .status = "inactive"});
    sqlgen::write(conn, Account{.account_id = 3, .balance = 500.0, .status = "active"});

    // Update balance and status for account_id = 1
    sqlgen::write(
        conn,
        sqlgen::update<Account>().set(
            sqlgen::columns(&Account::balance, &Account::status),
            std::make_tuple(1500.0, std::string("inactive"))
        ).where(sqlgen::eq(&Account::account_id, 1))
    );

    // Update only balance for account_id = 2
    sqlgen::write(
        conn,
        sqlgen::update<Account>().set(
            sqlgen::columns(&Account::balance),
            std::make_tuple(3000.0)
        ).where(sqlgen::eq(&Account::account_id, 2))
    );

    // Update only status for account_id = 3
    sqlgen::write(
        conn,
        sqlgen::update<Account>().set(
            sqlgen::columns(&Account::status),
            std::make_tuple(std::string("inactive"))
        ).where(sqlgen::eq(&Account::account_id, 3))
    );

    // Verify changes persisted by reading the updated records
    auto updated_account_1 = sqlgen::read_one<Account>(conn, sqlgen::where(sqlgen::eq(&Account::account_id, 1))).value();
    auto updated_account_2 = sqlgen::read_one<Account>(conn, sqlgen::where(sqlgen::eq(&Account::account_id, 2))).value();
    auto updated_account_3 = sqlgen::read_one<Account>(conn, sqlgen::where(sqlgen::eq(&Account::account_id, 3))).value();

    // Check if updates were applied correctly
    if (!(updated_account_1.balance == 1500.0 && updated_account_1.status == "inactive")) {
      return false;
    }

    if (!(updated_account_2.balance == 3000.0 && updated_account_2.status == "inactive")) {
      return false;
    }

    if (!(updated_account_3.balance == 500.0 && updated_account_3.status == "inactive")) {
      return false;
    }

    return true;
  } catch (...) {
    return false;
  }
}

}  // namespace update_set_operations
