```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace full_join_suppliers_products {

struct Supplier {
  sqlgen::PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  // Connect to SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

  // Perform FULL JOIN using sqlgen select_from with join
  using namespace sqlgen::literals;

  // Since sqlgen might not directly support FULL JOIN, we simulate it with LEFT JOIN + RIGHT JOIN
  // But for simplicity and since SQLite has limited FULL JOIN support, we'll use a UNION approach

  // First get all suppliers with their products (LEFT JOIN part)
  const auto left_join_query = 
    sqlgen::select_from<Supplier>()
    .columns<"name", "supplier_id">()
    .left_join<Product>()
    .on<"supplier_id">()
    .columns<"Product.name">();

  const auto left_results = sqlgen::read<std::vector<std::tuple<std::string, std::optional<int>, std::optional<std::string>>>>(conn, left_join_query).value();

  // Then get products without matching suppliers (RIGHT JOIN part - products with no matching supplier)
  const auto right_join_query = 
    sqlgen::select_from<Product>()
    .where<"supplier_id">(sqlgen::is_null)
    .columns<"supplier_id", "name">();

  const auto right_results = sqlgen::read<std::vector<std::tuple<std::optional<int>, std::string>>>(conn, right_join_query).value();

  std::vector<SupProd> result;

  // Process left join results
  for (const auto& [supplier_name, supplier_id, product_name] : left_results) {
    result.push_back(SupProd{supplier_name, product_name});
  }

  // Process right join results (products with no supplier)
  for (const auto& [supplier_id, product_name] : right_results) {
    result.push_back(SupProd{"", product_name});
  }

  return result;
}

}  // namespace full_join_suppliers_products
