```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Drop tables if they exist
  conn.and_then(sqlgen::drop<Department> | sqlgen::if_exists);
  conn.and_then(sqlgen::drop<Employee> | sqlgen::if_exists);

  // Create tables
  conn.and_then(sqlgen::create<Department>);
  conn.and_then(sqlgen::create<Employee>);

  // Insert data
  conn.and_then(sqlgen::write(depts));
  conn.and_then(sqlgen::write(emps));

  JoinAnalysis analysis;

  // INNER JOIN
  analysis.inner_join_results = conn.and_then(
    sqlgen::select_from<Department, Employee>()
    .columns<&Department::department_name, &Employee::first_name, &Employee::last_name, &Employee::salary>()
    .inner_join_on<&Department::department_id, &Employee::department_id>()
  ).value();

  // LEFT JOIN (All employees, even without departments)
  analysis.left_join_results = conn.and_then(
    sqlgen::select_from<Employee, Department>()
    .columns<&Department::department_name, &Employee::first_name, &Employee::last_name, &Employee::salary>()
    .left_join_on<&Employee::department_id, &Department::department_id>()
  ).value();

  // RIGHT JOIN (All departments, even without employees)
  analysis.right_join_results = conn.and_then(
    sqlgen::select_from<Department, Employee>()
    .columns<&Department::department_name, &Employee::first_name, &Employee::last_name, &Employee::salary>()
    .right_join_on<&Department::department_id, &Employee::department_id>()
  ).value();

  // FULL JOIN (All employees and departments)
  analysis.full_join_results = conn.and_then(
    sqlgen::select_from<Department, Employee>()
    .columns<&Department::department_name, &Employee::first_name, &Employee::last_name, &Employee::salary>()
    .full_join_on<&Department::department_id, &Employee::department_id>()
  ).value();

  return analysis;
}

}  // namespace analyze_department_employees
```

