#include <gtest/gtest.h>
#include "delete_with_complex_condition.hpp"

TEST(delete_with_complex_condition, test_query_generation) {
    std::string sql = delete_with_complex_condition::delete_with_complex_condition();
    EXPECT_TRUE(sql.find("DELETE FROM") != std::string::npos);
    EXPECT_TRUE(sql.find("User") != std::string::npos);
    EXPECT_TRUE(sql.find("WHERE") != std::string::npos);
    EXPECT_TRUE(sql.find("age") != std::string::npos);
    EXPECT_TRUE(sql.find("18") != std::string::npos);
    EXPECT_TRUE(sql.find("OR") != std::string::npos);
    EXPECT_TRUE(sql.find("status") != std::string::npos);
    EXPECT_TRUE(sql.find("inactive") != std::string::npos);
}

