```python
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Create the SQL query using sqlgen dynamic query building
  auto query = sqlgen::dynamic::select("Product", {"product_id", "product_name", "category"})
    .inner_join("Sales", "Product.product_id = Sales.product_id")
    .group_by({"Product.product_id", "Product.product_name", "Product.category"})
    .order_by({"SUM(Product.price * Sales.quantity) DESC"})
    .limit(limit_count);

  // Execute the query and fetch results
  auto result = sqlgen::read<std::vector<TopProduct>>(conn, query);

  // Check if the result is valid and return it, otherwise return an empty vector
  if (result.has_value()) {
    return result.value();
  } else {
    return {};
  }
}

}  // namespace get_top_products
```

