  int total_quantity;
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Query to extract weekday and sum quantity grouped by weekday
  // In SQLite, strftime('%w', date) returns weekday (0=Sunday, 6=Saturday)
  const auto query = R"(
    SELECT CAST(strftime('%w', sale_time) AS INTEGER) as weekday, SUM(quantity) as total_quantity
    FROM Sales
    GROUP BY strftime('%w', sale_time)
    ORDER BY weekday
  )";

  return sqlgen::read<std::vector<WeekdayStats>>(conn, query).value();
}

}  // namespace weekday_sales_analysis

