namespace group_by_with_aggregations {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  auto conn = sqlgen::sqlite::connect("test_db.sqlite").value();

  auto query = sqlgen::select_from<User, Post>()
    .columns(
      User{}.user_id,
      User{}.name,
      sqlgen::count(Post{}.post_id).as("post_count"),
      sqlgen::avg(sqlgen::length(Post{}.content)).as("avg_length")
    )
    .join<Post>(sqlgen::on(User{}.user_id == Post{}.user_id))
    .group_by(User{}.user_id, User{}.name);

  return sqlgen::read<std::vector<Stats>>(conn, query).value();
}

}  // namespace group_by_with_aggregations
